import React, { useState, useEffect } from "react";
import {
  DashboardIcon,
  UsersIcon,
  TasksIcon,
  MetricsIcon,
  SettingsIcon,
  CloseIcon,
} from "./Icons";

interface SidebarProps {
  isOpen: boolean;
  isCollapsed: boolean;
  onToggle: () => void;
  onCollapse: () => void;
  currentView: string;
  onViewChange: (view: string) => void;
}

const menuItems = [
  {
    id: "dashboard",
    name: "Dashboard",
    icon: DashboardIcon,
  },
  {
    id: "clients",
    name: "Clients",
    icon: UsersIcon,
  },
  {
    id: "tasks",
    name: "Tasks",
    icon: TasksIcon,
  },
  {
    id: "metrics",
    name: "Metrics",
    icon: MetricsIcon,
  },
  {
    id: "settings",
    name: "Settings",
    icon: SettingsIcon,
  },
];

export const Sidebar: React.FC<SidebarProps> = ({
  isOpen,
  isCollapsed,
  onToggle,
  onCollapse,
  currentView,
  onViewChange,
}) => {
  const [systemStatus, setSystemStatus] = useState({
    status: "operational" as "operational" | "warning" | "error",
    message: "All systems operational",
    color: "bg-green-500",
    bgColor: "bg-green-100",
  });

  // Простий статус без автоматичного перемикання
  useEffect(() => {
    // Можна додати реальну логіку перевірки статусу тут
    const currentStatus = {
      status: "operational" as const,
      message: "All systems operational",
      color: "bg-green-500",
      bgColor: "bg-green-100",
    };
    setSystemStatus(currentStatus);
  }, []);

  const renderSystemStatus = () => (
    <div className="group relative bg-gradient-to-br from-white to-secondary-50 rounded-xl border border-secondary-200 shadow-lg transition-all duration-300 overflow-hidden hover:shadow-xl hover:border-success-300">
      <div
        className={`flex items-center ${isCollapsed ? "p-3 justify-center" : "p-4"}`}
      >
        {/* Enhanced status indicator */}
        <div className={`relative ${isCollapsed ? "" : "mr-3"}`}>
          <div className="w-4 h-4 bg-gradient-to-r from-success-400 to-success-600 rounded-full shadow-lg animate-pulse"></div>
          <div className="absolute inset-0 w-4 h-4 bg-success-400 rounded-full animate-ping opacity-20"></div>
        </div>

        {/* Enhanced text information */}
        {!isCollapsed && (
          <div className="min-w-0 flex-1">
            <div className="flex items-center space-x-2">
              <p className="text-sm font-semibold text-secondary-900 truncate">
                System Status
              </p>
              <div className="px-2 py-1 bg-success-100 text-success-700 text-xs font-medium rounded-full">
                Online
              </div>
            </div>
            <p className="text-xs text-secondary-600 truncate mt-1">
              {systemStatus.message}
            </p>
          </div>
        )}
      </div>

      {/* Enhanced tooltip for collapsed state */}
      {isCollapsed && (
        <div className="absolute left-full ml-4 top-1/2 transform -translate-y-1/2 bg-secondary-900 text-white text-sm rounded-xl px-4 py-3 opacity-0 group-hover:opacity-100 transition-all duration-300 pointer-events-none z-50 whitespace-nowrap shadow-2xl border border-secondary-700">
          <div className="flex items-center space-x-2">
            <div className="w-2 h-2 bg-success-500 rounded-full animate-pulse" />
            <div>
              <p className="font-medium">System Status</p>
              <p className="text-xs text-secondary-300">{systemStatus.message}</p>
            </div>
          </div>
          {/* Tooltip arrow */}
          <div className="absolute left-0 top-1/2 transform -translate-x-1 -translate-y-1/2 w-2 h-2 bg-secondary-900 rotate-45 border-l border-b border-secondary-700" />
        </div>
      )}
    </div>
  );

  return (
    <>
      {/* Desktop Sidebar */}
      <div
        className={`hidden lg:flex lg:flex-col lg:fixed lg:inset-y-0 transition-all duration-300 z-30 ${
          isCollapsed ? "lg:w-20" : "lg:w-64"
        }`}
      >
        <div className="flex flex-col flex-grow bg-white shadow-lg border-r border-secondary-200">
          {/* Logo section */}
          <div
            className={`flex items-center flex-shrink-0 px-4 py-6 border-b border-secondary-100 ${isCollapsed ? "justify-center" : ""}`}
          >
            <div className="flex items-center">
              <div className="flex-shrink-0 w-10 h-10 gradient-primary rounded-lg flex items-center justify-center shadow-md">
                <span className="text-sm font-bold text-white">TC</span>
              </div>
              {!isCollapsed && (
                <div className="ml-3 transition-all duration-300">
                  <h2 className="text-base font-semibold text-secondary-900">
                    TetraCore
                  </h2>
                  <p className="text-xs text-secondary-500">StreamHub</p>
                </div>
              )}
            </div>
          </div>

          {/* Navigation */}
          <nav className="flex-1 px-3 py-6 space-y-3">
            {menuItems.map((item) => {
              const isActive = currentView === item.id;
              const IconComponent = item.icon;

              return (
                <div key={item.id} className="relative group">
                  <button
                    onClick={() => onViewChange(item.id)}
                    className={`w-full flex items-center text-sm font-medium rounded-xl transition-all duration-300 relative overflow-hidden group ${
                      isActive
                        ? "bg-gradient-to-r from-primary-500 to-primary-600 text-white shadow-lg shadow-primary-500/25 scale-105"
                        : "text-secondary-600 hover:bg-gradient-to-r hover:from-secondary-50 hover:to-secondary-100 hover:text-secondary-900 hover:shadow-md hover:scale-102"
                    } ${isCollapsed ? "px-3 py-4 justify-center" : "px-4 py-4"}`}
                  >
                    {/* Animated background effect */}
                    <div className={`absolute inset-0 transition-all duration-300 ${
                      isActive 
                        ? "bg-gradient-to-r from-primary-500 to-primary-600" 
                        : "bg-gradient-to-r from-transparent to-transparent group-hover:from-primary-50 group-hover:to-primary-100"
                    }`} />

                    {/* Icon with enhanced styling */}
                    <div className={`relative flex-shrink-0 transition-all duration-300 ${
                      isActive 
                        ? "text-white transform scale-110" 
                        : "text-secondary-500 group-hover:text-primary-600 group-hover:transform group-hover:scale-110"
                    } ${isCollapsed ? "" : "mr-4"}`}>
                      <div className={`p-2 rounded-lg transition-all duration-300 ${
                        isActive 
                          ? "bg-white/20 shadow-lg" 
                          : "group-hover:bg-primary-100/50"
                      }`}>
                        <IconComponent size="lg" />
                      </div>
                    </div>

                    {/* Text with enhanced animation */}
                    {!isCollapsed && (
                      <span className="relative transition-all duration-300 font-semibold">
                        {item.name}
                      </span>
                    )}

                    {/* Active indicator */}
                    {isActive && (
                      <div className="absolute right-2 w-2 h-2 bg-white rounded-full shadow-lg animate-pulse" />
                    )}
                  </button>

                  {/* Enhanced tooltip for collapsed state */}
                  {isCollapsed && (
                    <div className="absolute left-full ml-4 top-1/2 transform -translate-y-1/2 bg-secondary-900 text-white text-sm rounded-xl px-4 py-3 opacity-0 group-hover:opacity-100 transition-all duration-300 pointer-events-none z-50 whitespace-nowrap shadow-2xl border border-secondary-700">
                      <div className="flex items-center space-x-2">
                        <div className="w-2 h-2 bg-primary-500 rounded-full animate-pulse" />
                        <span className="font-medium">{item.name}</span>
                      </div>
                      {/* Tooltip arrow */}
                      <div className="absolute left-0 top-1/2 transform -translate-x-1 -translate-y-1/2 w-2 h-2 bg-secondary-900 rotate-45 border-l border-b border-secondary-700" />
                    </div>
                  )}
                </div>
              );
            })}
          </nav>

          {/* Enhanced Footer */}
          <div className="flex-shrink-0 p-4 border-t border-secondary-100">
            {renderSystemStatus()}

            {/* Collapse button with enhanced design */}
            <button
              onClick={onCollapse}
              className={`mt-4 w-full flex items-center justify-center text-sm font-medium rounded-xl transition-all duration-300 py-3 px-3 bg-gradient-to-r from-secondary-100 to-secondary-200 text-secondary-700 hover:from-primary-100 hover:to-primary-200 hover:text-primary-700 hover:shadow-md group ${
                isCollapsed ? "px-3" : "px-4"
              }`}
            >
              <div className="p-1 rounded-lg bg-white/50 group-hover:bg-white/80 transition-all duration-300">
                <svg
                  className={`w-4 h-4 transition-transform duration-300 ${
                    isCollapsed ? "rotate-180" : ""
                  }`}
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M11 19l-7-7 7-7m8 14l-7-7 7-7"
                  />
                </svg>
              </div>
              {!isCollapsed && (
                <span className="ml-2 font-semibold">Згорнути</span>
              )}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Sidebar */}
      <div
        className={`lg:hidden fixed inset-0 z-50 transition-transform duration-300 ${
          isOpen ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="flex">
          {/* Sidebar content */}
          <div className="flex flex-col w-64 bg-white shadow-xl">
            {/* Logo section */}
            <div className="flex items-center justify-between flex-shrink-0 px-4 py-4 border-b border-secondary-200">
              <div className="flex items-center">
                <div className="flex-shrink-0 w-8 h-8 gradient-primary rounded-lg flex items-center justify-center shadow-md">
                  <span className="text-sm font-bold text-white">TC</span>
                </div>
                <div className="ml-3">
                  <h2 className="text-sm font-semibold text-secondary-900">
                    TetraCore
                  </h2>
                  <p className="text-xs text-secondary-500">StreamHub</p>
                </div>
              </div>
              <button
                onClick={onToggle}
                className="p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-lg transition-colors duration-200"
              >
                <CloseIcon size="lg" />
              </button>
            </div>

            {/* Navigation */}
            <nav className="flex-1 px-3 py-4 space-y-2">
              {menuItems.map((item) => {
                const isActive = currentView === item.id;
                const IconComponent = item.icon;

                return (
                  <button
                    key={item.id}
                    onClick={() => {
                      onViewChange(item.id);
                      onToggle(); // Close mobile sidebar after selection
                    }}
                    className={`group flex items-center w-full px-4 py-4 text-sm font-medium rounded-xl transition-all duration-300 relative overflow-hidden ${
                      isActive
                        ? "bg-gradient-to-r from-primary-500 to-primary-600 text-white shadow-lg shadow-primary-500/25"
                        : "text-secondary-600 hover:bg-gradient-to-r hover:from-secondary-50 hover:to-secondary-100 hover:text-secondary-900 hover:shadow-md"
                    }`}
                  >
                    {/* Animated background effect */}
                    <div className={`absolute inset-0 transition-all duration-300 ${
                      isActive 
                        ? "bg-gradient-to-r from-primary-500 to-primary-600" 
                        : "bg-gradient-to-r from-transparent to-transparent group-hover:from-primary-50 group-hover:to-primary-100"
                    }`} />

                    {/* Enhanced icon */}
                    <div className={`relative flex-shrink-0 mr-4 transition-all duration-300 ${
                      isActive 
                        ? "text-white transform scale-110" 
                        : "text-secondary-500 group-hover:text-primary-600 group-hover:transform group-hover:scale-110"
                    }`}>
                      <div className={`p-2 rounded-lg transition-all duration-300 ${
                        isActive 
                          ? "bg-white/20 shadow-lg" 
                          : "group-hover:bg-primary-100/50"
                      }`}>
                        <IconComponent size="lg" />
                      </div>
                    </div>

                    {/* Enhanced text */}
                    <span className="relative font-semibold">{item.name}</span>

                    {/* Active indicator */}
                    {isActive && (
                      <div className="absolute right-3 w-2 h-2 bg-white rounded-full shadow-lg animate-pulse" />
                    )}
                  </button>
                );
              })}
            </nav>

            {/* Footer */}
            <div className="flex-shrink-0 p-4 border-t border-secondary-200">
              {renderSystemStatus()}
            </div>
          </div>
        </div>
      </div>
    </>
  );
};
